      sessionId: 's1',
      message: 'ready',
      examplePrompts: [],
    } satisfies ConnectedMessage;
    const previousOutgoing: OutgoingMessage[] = [
      {type: 'entry_upsert', index: 0, entry},
      {type: 'entry_delta', index: 0, delta: 'hello'},
      {type: 'entry_commit', index: 0},
      {type: 'entry_skip', index: 0},
      {type: 'error', code: 'SERVER_ERROR', message: 'failed'},
      {type: 'pong', timestamp: 1},
      {type: 'stream_end'},
    ];
    const summary: SessionSummaryFrame = {
      sessionId: 's1',
      createdAt: '2026-01-01T00:00:00.000Z',
      updatedAt: '2026-01-02T00:00:00.000Z',
      entryCount: 2,
