    expect(existingIncoming.map(message => message.type)).toEqual(['user_message', 'ping']);
    expect(listRequest.type).toBe('list_sessions');
    expect(existingOutgoing.type).toBe('connected');
    expect(previousOutgoing.map(message => message.type)).toEqual([
      'entry_upsert',
      'entry_delta',
      'entry_commit',
      'entry_skip',
      'error',
      'pong',
      'stream_end',
    ]);
    expect(listed.type).toBe('session_list');
  });
});
